vector<int> bfs(int n, int m, vector<vector<int>> edges, int start_node)
{
    vector<vector<int>> neighbors(n + 1);

    for (auto &e : edges) {
        int u = e[0];
        int v = e[1];
        neighbors[u].push_back(v);
        neighbors[v].push_back(u);
    }

    vector<int> distances(n + 1, -1);
    distances[start_node] = 0;

    queue<int> q;
    q.push(start_node);

    while (!q.empty()) {
        int cur = q.front();
        q.pop();

        for (int nxt : neighbors[cur]) {
            if (distances[nxt] == -1) {
                distances[nxt] = distances[cur] + 6;
                q.push(nxt);
            }
        }
    }

    vector<int> result;
    for (int i = 1; i <= n; i++) {
        if (i != start_node)
            result.push_back(distances[i]);
    }

    return result;
}

